const createNodeSpec: OperationSpec = {
  operationName: 'createNode',
  method: 'POST',
  path: '/nodes',
  tags: ['nodes'],
  security: [],
  params: [],
  body: { kind: 'json', mediaType: 'application/json' },
  responses: { '201': 'json' },
};

/**
 * Echo a tree of nodes back, assigning ids
 */
export const createNode = <ThrowOnError extends boolean = false>(options: Options<CreateNodeData, ThrowOnError>) =>
  (options.client ?? client).request<CreateNodeResponse, CreateNodeError, ThrowOnError>(createNodeSpec, options);
